public class Main {
    public static void main(String[] args) {
        String s = "{word}";
        System.out.println("这串有 " + s.length() + " 颗");
        System.out.println("编号 {k} 那颗是 " + s.charAt({k}));
        System.out.println("从头剪到编号 {k} 之前：" + s.substring(0, {k}));
        System.out.println("最后一颗是 " + s.charAt(s.length() - 1));
    }
}
